from __future__ import annotations

from math import ceil, log2
from typing import Literal

from flint import acb, arb, ctx


InputMode = Literal["auto", "real", "complex"]


def as_acb_and_mode(value, mode: InputMode) -> tuple[acb, bool, int | None]:
    """Convert input to Acb and determine whether to use a complex lattice.

    The returned source-precision cap prevents a Python binary64 value from
    acquiring fictitious accuracy merely because it is converted at a large
    FLINT working precision.
    """
    if mode not in {"auto", "real", "complex"}:
        raise ValueError("mode must be 'auto', 'real', or 'complex'")

    source_cap: int | None = None

    if isinstance(value, acb):
        z = value
    elif isinstance(value, arb):
        z = acb(value)
    elif isinstance(value, complex):
        z = acb(value)
        source_cap = 53
    elif isinstance(value, float):
        z = acb(value)
        source_cap = 53
    elif isinstance(value, int):
        z = acb(value)
    else:
        z = acb(value)

    if not z.is_finite():
        raise ValueError("value must be finite")

    if mode == "real":
        if not z.imag.contains(0):
            raise ValueError(
                "mode='real' requires an input compatible with the real axis"
            )
        use_complex = False
    elif mode == "complex":
        use_complex = True
    else:
        # Conservative: use the smaller real lattice only when the imaginary
        # component is provably exactly zero.
        use_complex = not z.imag.is_zero()

    return z, use_complex, source_cap


def usable_accuracy_bits(value: acb, source_cap: int | None) -> int:
    """Estimate trustworthy input bits without confusing them with ctx.prec."""
    accuracy = int(value.rel_accuracy_bits())
    accuracy = min(accuracy, int(ctx.prec))

    if source_cap is not None:
        accuracy = min(accuracy, source_cap)

    return max(0, accuracy)


def binary_magnitude_exponent(value: acb) -> int:
    """Return a coarse upper binary exponent for ``abs(value)``.

    The result is an integer ``e`` such that values with magnitude near
    ``2**e`` have exponent ``e``. Only exponent-scale information is needed
    for lattice balancing, so this deliberately avoids conversion to
    binary64.

    ``acb.abs_upper()`` supplies a rigorous magnitude upper bound; extracting
    the midpoint's binary mantissa/exponent is sufficient for this heuristic
    scaling decision. A one-bit safety margin is included.
    """
    magnitude = value.abs_upper()

    if magnitude.is_zero():
        return 0

    midpoint = magnitude.mid()
    mantissa_fmpz, exponent_fmpz = midpoint.man_exp()
    mantissa = abs(int(mantissa_fmpz))
    exponent = int(exponent_fmpz)

    if mantissa == 0:
        return 0

    # floor(log2(midpoint)) + 1, with an extra bit of safety because the
    # magnitude object is an enclosure rather than a mathematically exact real.
    return mantissa.bit_length() + exponent + 1


def choose_scale_bits(
    accuracy_bits: int,
    degree: int,
    magnitude_exponent_bits: int,
    override: int | None,
) -> int:
    """Choose a magnitude-aware binary lattice scaling exponent.

    Ignoring guard bits, the strategy is the binary analogue of

        max(accuracy - degree*log2(|x|), accuracy/2).

    When |x| is large, powers x**i already make the residual columns large, so
    a full ``2**accuracy`` scale would overemphasize the residual coordinates
    and inflate lattice entries. The magnitude correction compensates for
    this growth. A half-accuracy floor prevents the scale from becoming too
    small.

    Reciprocal normalization normally ensures the search value has |x| >= 1,
    so negative magnitude exponents are ignored.
    """
    if override is not None:
        if override < 8:
            raise ValueError("lattice_scale_bits must be at least 8")
        if override > accuracy_bits:
            raise ValueError(
                "lattice_scale_bits cannot exceed the estimated trustworthy "
                "input accuracy"
            )
        return override

    guard = 8 + ceil(log2(degree + 1))
    growth_bits = degree * max(0, magnitude_exponent_bits)

    magnitude_adjusted = accuracy_bits - growth_bits
    half_accuracy_floor = accuracy_bits // 2
    target = max(magnitude_adjusted, half_accuracy_floor)

    return max(16, target - guard)


def working_precision_bits(accuracy_bits: int, degree: int, value: acb) -> int:
    """Choose guard precision for power formation and residual evaluation.

    The growth term is based on the binary magnitude exponent of ``value``.
    If |x| is roughly 2**e, then x**degree can require roughly
    ``degree * max(e, 0)`` additional exponent-scale bits during intermediate
    calculations. This is the quantity relevant to power growth; it is more
    appropriate here than inspecting an Arb object's storage/precision size.
    """
    magnitude_exponent = max(0, binary_magnitude_exponent(value))
    guard = (
        24
        + ceil(log2(degree + 1))
        + degree * magnitude_exponent
    )
    return max(int(ctx.prec), accuracy_bits + guard)


def round_arb_midpoint_to_int(value: arb) -> int:
    """Round the exact binary midpoint of an Arb ball to nearest integer."""
    midpoint = value.mid()
    mantissa_fmpz, exponent_fmpz = midpoint.man_exp()
    mantissa = int(mantissa_fmpz)
    exponent = int(exponent_fmpz)

    if exponent >= 0:
        return mantissa << exponent

    denominator = 1 << (-exponent)

    if mantissa >= 0:
        return (mantissa + denominator // 2) // denominator

    return -((-mantissa + denominator // 2) // denominator)


def arb_log2_positive(value: arb) -> arb:
    """Return log2(value) for a provably positive Arb value."""
    if value <= 0:
        raise ValueError("arb_log2_positive requires a positive value")
    return value.log() / arb(2).log()
